while True:
	sp_check_0.scan()
	sleep(3)
	if sp_check_0:
		while True:
			road_1.scan()
			if not road_1:	
				kb_press("w")
				sleep(0.05)
			else:
				log("Found road")
				break
		while True:
			road_2.scan()
			if not road_2:	
				kb_press("d")
				sleep(0.1)
			else:
				log("On tri section")
				break
		while True:
			event_spinner_check.scan()
			if event_spinner_check and not road_3.group_1.color_scan():	
				kb_press("w")
			else:
				road_1.scan()
				if not road_1:	
					kb_press("w")
				else:
					log("Last Road")
					break
		while True:
			if not road_4.group_1.color_scan() and not road_4.group_2.color_scan():	
				kb_press("a")
				sleep(0.1)
			else:
				log("Found road")
				break
		while True:
			table_ylw.scan()
			if not table_ylw:	
				kb_press("w")
				sleep(0.1)
			else:
				log("Found Table")
				break
		while True:
			super_roll_1.scan()
			super_roll_2.scan()
			if not (super_roll_1 or super_roll_2):
				kb_press("w")
				if TableSide == 'Left':
					kb_press("a")
				else:
					kb_press("d")
				sleep(0.1)
			else:
				log("Sat on Table")
				break

	sleep(1)
